// ListDirs .
// @router /api/v1/system/dirs [GET]
func ListDirs(ctx context.Context, c *app.RequestContext) {
	handler.BindAndDo(c,
		func(req *systemModel.ListDirsRequest) (map[string]interface{}, error) {
			currentPath := req.Path
			if currentPath == "" {
				home, err := os.UserHomeDir()
				if err != nil {
					currentPath = "/"
				} else {
					currentPath = home
				}
			}

			entries, err := os.ReadDir(currentPath)
			if err != nil {
				return nil, handler.ErrInternal(err.Error())
			}

			var dirs []*systemModel.DirEntry
			for _, entry := range entries {
				if entry.IsDir() && !strings.HasPrefix(entry.Name(), ".") {
					if req.Search != "" && !strings.Contains(strings.ToLower(entry.Name()), strings.ToLower(req.Search)) {
						continue
					}
					dirs = append(dirs, &systemModel.DirEntry{
						Name:  entry.Name(),
						Path:  filepath.Join(currentPath, entry.Name()),
						IsDir: true,
					})
				}
			}

			slices.SortFunc(dirs, func(a, b *systemModel.DirEntry) int {
				return strings.Compare(a.Name, b.Name)
			})

			parent := filepath.Dir(currentPath)
			if currentPath == "/" {
				parent = ""
			}

			return map[string]interface{}{
				"parent":  parent,
				"current": currentPath,
				"dirs":    dirs,
			}, nil
		},
	)
}

// ListSSHKeys .
// @router /api/v1/system/ssh-keys [GET]
func ListSSHKeys(ctx context.Context, c *app.RequestContext) {
	home, err := os.UserHomeDir()
	if err != nil {
		response.InternalServerError(c, "cannot find home dir")
		return
	}

	sshDir := filepath.Join(home, ".ssh")
	entries, err := os.ReadDir(sshDir)
	if err != nil {
		response.Success(c, []*systemModel.SSHKey{})
		return
	}

	var keys []*systemModel.SSHKey
	for _, entry := range entries {
		if !entry.IsDir() {
			keys = append(keys, &systemModel.SSHKey{
				Name: entry.Name(),
				Path: filepath.Join(sshDir, entry.Name()),
			})
		}
	}

	response.Success(c, keys)
}

