// SelectDirectory 打开系统目录选择对话框
// @router /api/v1/system/select-directory [POST]
func SelectDirectory(ctx context.Context, c *app.RequestContext) {
	var req struct {
		Title string `json:"title"`
	}
	_ = c.Bind(&req)

	title := req.Title
	if title == "" {
		title = "选择目录"
	}

	// 尝试根据操作系统打开目录选择对话框
	var result string
	var err error

	switch runtime.GOOS {
	case "darwin":
		// macOS: 使用 osascript
		script := fmt.Sprintf(`tell application "System Events" to activate
return POSIX path of (choose folder with prompt "%s")`, title)
		result, err = execCommand("osascript", "-e", script)
	case "windows":
		// Windows: 使用 powershell
		cmd := fmt.Sprintf(`Add-Type -AssemblyName System.Windows.Forms; $f = New-Object System.Windows.Forms.FolderBrowserDialog; $f.Description = '%s'; $f.ShowDialog() | Out-Null; if ($f.SelectedPath) { Write-Output $f.SelectedPath }`, title)
		result, err = execCommand("powershell", "-Command", cmd)
	default:
		// Linux 或其他系统: 返回错误，建议使用目录浏览功能
		errorMsg := "Directory dialog not supported on this platform. Please use the directory browser instead."
		response.InternalServerError(c, errorMsg)
		return
	}

	if err != nil {
		// 检查是否是用户取消
		errMsg := err.Error()
		if strings.Contains(errMsg, "User canceled") || strings.Contains(errMsg, "用户取消") || strings.Contains(errMsg, "用户已取消") || strings.Contains(errMsg, "-128") {
			response.Success(c, map[string]string{"path": "", "cancelled": "true"})
			return
		}
		// 提供备选方案：使用目录浏览功能
		errorMsg := "Failed to open directory dialog: " + errMsg + ". Please use the directory browser instead."
		response.InternalServerError(c, errorMsg)
		return
	}

	path := strings.TrimSpace(result)
	if path == "" {
		response.Success(c, map[string]string{"path": "", "cancelled": "true"})
		return
	}

	response.Success(c, map[string]string{"path": path, "cancelled": "false"})
}

// execCommand 执行系统命令并返回输出
func execCommand(name string, args ...string) (string, error) {
	cmd := exec.Command(name, args...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		// 返回包含 stderr 的详细错误信息
		return "", fmt.Errorf("%v: %s", err, strings.TrimSpace(string(output)))
	}
	return string(output), nil
}
